create table public.companies (id uuid primary key default gen_random_uuid(), name text not null, company_code text not null, created_at timestamptz not null default now());
create unique index companies_company_code_key on public.companies (company_code);
create table public.profiles (id uuid primary key references auth.users (id) on delete cascade, company_id uuid not null references public.companies (id) on delete restrict, role text not null default 'employee' check (role in ('employee','super_admin')), nickname text not null check (char_length(nickname) between 1 and 20), ranking_opt_in boolean not null default true, notification_enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quests (id uuid primary key default gen_random_uuid(), title text not null check (char_length(title) between 1 and 100), description text not null check (char_length(description) between 1 and 500), category text not null check (category in ('exercise','posture','hydration','nutrition','sleep','mental','focus')), duration_seconds integer not null check (duration_seconds between 1 and 600), points integer not null check (points between 1 and 1000), scheduled_at timestamptz not null, expires_at timestamptz not null, notification_title text not null check (char_length(notification_title) between 1 and 60), notification_body text not null check (char_length(notification_body) between 1 and 120), status text not null default 'draft' check (status in ('draft','scheduled','published','stopped')), created_by uuid not null references public.profiles (id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint quests_expires_after_scheduled check (expires_at > scheduled_at));
alter table public.quests add constraint quests_no_overlapping_active_window exclude using gist (tstzrange(scheduled_at, expires_at, '[)') with &&) where (status in ('scheduled','published'));
create table public.daily_quests (id uuid primary key default gen_random_uuid(), title text not null, description text not null, category text not null check (category in ('exercise','posture','hydration','nutrition','sleep','mental','focus')), points integer not null check (points between 1 and 1000), sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.quest_completions (id uuid primary key default gen_random_uuid(), quest_id uuid not null references public.quests (id) on delete cascade, user_id uuid not null references public.profiles (id) on delete cascade, company_id uuid not null references public.companies (id), completed_at timestamptz not null default now(), unique (quest_id, user_id));
create table public.daily_quest_completions (id uuid primary key default gen_random_uuid(), daily_quest_id uuid not null references public.daily_quests (id) on delete cascade, user_id uuid not null references public.profiles (id) on delete cascade, company_id uuid not null references public.companies (id), completed_date date not null, completed_at timestamptz not null default now(), unique (daily_quest_id, user_id, completed_date));
create table public.points_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles (id) on delete cascade, company_id uuid not null references public.companies (id), reason_type text not null check (reason_type in ('instant_quest','daily_quest','adjustment')), quest_id uuid references public.quests (id), daily_quest_id uuid references public.daily_quests (id), points integer not null, is_reversed boolean not null default false, created_at timestamptz not null default now());
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles (id) on delete cascade, endpoint text not null, p256dh text not null, auth text not null, created_at timestamptz not null default now());
create unique index push_subscriptions_endpoint_key on public.push_subscriptions (endpoint);
create table public.notification_deliveries (id uuid primary key default gen_random_uuid(), quest_id uuid not null references public.quests (id) on delete cascade, subscription_id uuid not null references public.push_subscriptions (id) on delete cascade, status text not null default 'pending' check (status in ('pending','sent','failed')), error_message text, delivered_at timestamptz, created_at timestamptz not null default now(), unique (quest_id, subscription_id));
